async function listEvents(req, res) {
  if (!req.auth?.userId) {
    return res.status(401).end();
  }

  const tenantId = req.query.tenantId;
  if (typeof tenantId !== "string") {
    return res.status(400).end();
  }

  const events = await db.event.findMany({
    where: { tenantId }
  });
  return res.json(events);
}
